import AppKit
import ClasifyCore
import SwiftUI
import Testing

@testable import ClasifySkins

/// Launch video only, not for merge: the real Pocket screens with a made-up library and
/// made-up covers, saved as large PNGs of the screen (300 x 225 points at 8x) when SNAPSHOT_DIR is set.
@Suite @MainActor struct LaunchVideoScreens {
    static let scale = 8
    static func coverID(_ i: Int) -> String { String(repeating: String(format: "%02x", 0xc0 + i), count: 20) }
    static let coverData: [String] = [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    ]
    static func cover(_ id: String) -> CGImage? {
        guard let i = (1...8).first(where: { coverID($0) == id }),
              let data = Data(base64Encoded: coverData[i - 1]) else { return nil }
        return NSBitmapImageRep(data: data)?.cgImage
    }

    func state() -> AppState {
        var s = AppState()
        s.signedIn = true
        s.setupDone = true
        s.activated = true
        s.stack = [Frame(screen: .main)]
        s.library = [
            Playlist(id: Playlist.likedSongsID, name: "Liked Songs", tracks: [
            Track(id: "spotify:track:v1", title: "Late Summer", artist: "June Harbor", duration: 214, coverID: Self.coverID(1),
                  album: Album(id: "spotify:album:v1", name: "Late Summer", artist: "June Harbor")),
            Track(id: "spotify:track:v2", title: "Night Bus", artist: "Mara Lune", duration: 231, coverID: Self.coverID(2),
                  album: Album(id: "spotify:album:v2", name: "Night Bus", artist: "Mara Lune")),
            Track(id: "spotify:track:v3", title: "Three Rings", artist: "Studio Ono", duration: 198, coverID: Self.coverID(3),
                  album: Album(id: "spotify:album:v3", name: "Three Rings", artist: "Studio Ono")),
            Track(id: "spotify:track:v4", title: "Signal", artist: "Kōji & the Wires", duration: 246, coverID: Self.coverID(4),
                  album: Album(id: "spotify:album:v4", name: "Signal", artist: "Kōji & the Wires")),
            Track(id: "spotify:track:v5", title: "Low Tide", artist: "Ines Vale", duration: 189, coverID: Self.coverID(5),
                  album: Album(id: "spotify:album:v5", name: "Low Tide", artist: "Ines Vale")),
            Track(id: "spotify:track:v6", title: "Peak Hours", artist: "Bright Annex", duration: 207, coverID: Self.coverID(6),
                  album: Album(id: "spotify:album:v6", name: "Peak Hours", artist: "Bright Annex")),
            Track(id: "spotify:track:v7", title: "Golden Hour", artist: "Satori Sound", duration: 223, coverID: Self.coverID(7),
                  album: Album(id: "spotify:album:v7", name: "Golden Hour", artist: "Satori Sound")),
            Track(id: "spotify:track:v8", title: "Moss", artist: "Field Notes", duration: 201, coverID: Self.coverID(8),
                  album: Album(id: "spotify:album:v8", name: "Moss", artist: "Field Notes"))
            ]),
            Playlist(id: "spotify:playlist:v1", name: "Night Drive", tracks: []),
            Playlist(id: "spotify:playlist:v2", name: "Sunday Morning", tracks: []),
            Playlist(id: "spotify:playlist:v3", name: "Deep Focus", tracks: []),
        ]
        s.current = TrackRef(playlist: Playlist.likedSongsID, track: "spotify:track:v2")
        s.isPlaying = true
        s.t = 67
        s.artRow = .nowPlaying
        s.refreshArt()
        return s
    }

    func save(_ s: AppState, _ name: String, time: Double = 1) throws {
        let art = Artwork { Self.cover($0) }
        let skin = PocketSkin(state: s, interactive: false, pressed: nil)
            .environment(\.artwork, art)
            .environment(\.animationTime, time)
        let renderer = ImageRenderer(content: skin)
        renderer.scale = CGFloat(Self.scale)
        let image = try #require(renderer.cgImage)
        let k = CGFloat(Self.scale)
        let screen = try #require(image.cropping(to: CGRect(x: 33 * k, y: 32.4 * k, width: 300 * k, height: 225 * k)))
        guard let dir = ProcessInfo.processInfo.environment["SNAPSHOT_DIR"] else { return }
        let rep = NSBitmapImageRep(cgImage: screen)
        let png = try #require(rep.representation(using: .png, properties: [:]))
        try png.write(to: URL(fileURLWithPath: dir).appendingPathComponent("video-\(name).png"))
        if name == "main-0" {
            let full = NSBitmapImageRep(cgImage: image)
            try #require(full.representation(using: .png, properties: [:]))
                .write(to: URL(fileURLWithPath: dir).appendingPathComponent("video-device-main.png"))
        }
    }

    @Test func screensForTheLaunchVideo() throws {
        var s = state()
        for sel in 0...6 {
            s.stack[0].sel = sel
            try save(s, "main-\(sel)", time: 1 + Double(sel) * 0.25)
        }
        s.stack[0].sel = 4
        s.stack.append(Frame(screen: .tracks(playlist: Playlist.likedSongsID)))
        for sel in 0...3 {
            s.stack[1].sel = sel
            try save(s, "liked-\(sel)")
        }
        s.stack[1].sel = 1
        s.stack.append(Frame(screen: .now))
        for t in [66.0, 67, 68, 69] {
            s.t = t
            try save(s, "now-\(Int(t))")
        }
        var g = state()
        g.stack[0].sel = 6
        g.stack.append(Frame(screen: .settings))
        try save(g, "settings-spotify")
        g.pendingService = .appleMusic
        try save(g, "settings-apple")
        g.pendingService = nil
        g.stack[1].sel = 4
        try save(g, "settings-color")
        var p = state()
        p.stack[0].sel = 2
        p.stack.append(Frame(screen: .playlists))
        try save(p, "playlists")
        var c = state()
        c.stack[0].sel = 1
        c.stack.append(Frame(screen: .coverFlow))
        try save(c, "coverflow")
    }
}
